package org.nhrc.grants.notifications

import java.time.OffsetDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter

data class BrandedEmail(val subject:String,val heading:String,val greeting:String,val message:String,val details:List<Pair<String,String>>,val nextStep:String,val actionLabel:String,val actionUrl:String,val portalUrl:String,val secondaryUrl:String?=null,val secondaryLabel:String="Open related workspace",val preheader:String="An update from NHRC eGMS",val securityNote:String="This message was sent to your registered NHRC eGMS account. Access and approval authority follow your assigned institutional roles.")
data class RenderedEmail(val subject:String,val plain:String,val html:String)
object EmailTemplates {
 fun escape(value:String)=value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;")
 fun timestamp(raw:Any):String { val value=when(raw){is OffsetDateTime->raw;is java.sql.Timestamp->raw.toInstant().atOffset(java.time.ZoneOffset.UTC);else->OffsetDateTime.parse(raw.toString())};return value.atZoneSameInstant(ZoneId.of("Europe/London")).format(DateTimeFormatter.ofPattern("dd MMM yyyy, HH:mm z")) }
 fun render(c:BrandedEmail):RenderedEmail {
  require(listOfNotNull(c.actionUrl,c.portalUrl,c.secondaryUrl).all {it.startsWith("http://localhost:") || it.startsWith("http://127.0.0.1:") || it.startsWith("https://")})
  val rows=c.details.filter{it.second.isNotBlank()}.joinToString(""){(key,value)->"<tr><th scope=\"row\" align=\"left\" valign=\"top\" style=\"padding:11px 16px;border-bottom:1px solid #e4ebf0;font:600 13px Arial,sans-serif;color:#4b6073;width:36%\">${escape(key)}</th><td style=\"padding:11px 16px;border-bottom:1px solid #e4ebf0;font:14px Arial,sans-serif;color:#17334a;word-break:break-word\">${escape(value)}</td></tr>"}
  val message=escape(c.message).replace("\n","<br/>")
  val secondary=if(c.secondaryUrl!=null)"<p style=\"margin:18px 0 0;font:14px Arial,sans-serif\"><a href=\"${escape(c.secondaryUrl)}\" style=\"color:#0c6b5b;text-decoration:underline\">${escape(c.secondaryLabel)}</a></p>" else ""
  val html="""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(c.subject)}</title></head><body style="margin:0;padding:0;background:#f1f5f8;color:#17334a"><div style="display:none;max-height:0;overflow:hidden;opacity:0">${escape(c.preheader)}</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f8"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="640" cellpadding="0" cellspacing="0" style="width:100%;max-width:640px;background:white;border:1px solid #dce5ec"><tr><td style="padding:26px 28px;background:#102f48"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="padding-right:16px"><img src="cid:nhrc-logo" alt="Navrongo Health Research Centre" width="64" height="56" style="display:block;object-fit:contain;background:white;border:0"></td><td><p style="margin:0;color:white;font:bold 23px Arial,sans-serif">NHRC eGMS</p><p style="margin:7px 0 0;color:#d2e3ed;font:13px Arial,sans-serif">Electronic Grant Management System</p></td></tr></table></td></tr><tr><td style="padding:30px 28px"><p style="margin:0 0 12px;color:#0c6b5b;font:bold 12px Arial,sans-serif;letter-spacing:1px">NAVRONGO HEALTH RESEARCH CENTRE</p><h1 style="margin:0 0 24px;font:bold 25px/1.3 Arial,sans-serif;color:#102f48">${escape(c.heading)}</h1><p style="font:15px/1.65 Arial,sans-serif;margin:0 0 16px">${escape(c.greeting)}</p><p style="font:15px/1.65 Arial,sans-serif;margin:0 0 24px">$message</p><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e4ebf0;border-collapse:collapse;background:#f8fafb">$rows</table><h2 style="margin:26px 0 10px;font:bold 17px Arial,sans-serif">What to do next</h2><p style="margin:0 0 24px;font:15px/1.65 Arial,sans-serif">${escape(c.nextStep)}</p><table role="presentation" cellpadding="0" cellspacing="0"><tr><td bgcolor="#0c6b5b" style="border-radius:4px"><a href="${escape(c.actionUrl)}" style="display:inline-block;padding:15px 23px;border:1px solid #0c6b5b;color:white;text-decoration:none;font:bold 15px Arial,sans-serif;border-radius:4px">${escape(c.actionLabel)}</a></td></tr></table>$secondary<p style="margin:23px 0 0;font:12px/1.65 Arial,sans-serif;color:#586e7e">If the button does not open, copy this link into your browser:<br/><a href="${escape(c.actionUrl)}" style="color:#0c6b5b;word-break:break-all">${escape(c.actionUrl)}</a></p></td></tr><tr><td style="padding:22px 28px;background:#f7fafb;border-top:1px solid #e4ebf0"><p style="margin:0 0 12px;font:12px/1.65 Arial,sans-serif;color:#586e7e">${escape(c.securityNote)}</p><p style="margin:0 0 12px;font:12px/1.65 Arial,sans-serif;color:#586e7e">Need help? Contact your institutional eGMS administrator. <a href="${escape(c.portalUrl)}" style="color:#0c6b5b">Open NHRC eGMS</a>.</p><p style="margin:0;font:11px/1.6 Arial,sans-serif;color:#586e7e">© ${java.time.Year.now().value} Navrongo Health Research Centre.<br/>This is an automated institutional message. Local UAT links work on the host computer; remote access requires an institution-accessible deployment.</p></td></tr></table></td></tr></table></body></html>"""
  val plain=listOf("NHRC eGMS - Electronic Grant Management System",c.heading,c.greeting,c.message,c.details.filter{it.second.isNotBlank()}.joinToString("\n"){"${it.first}: ${it.second}"},"What to do next: ${c.nextStep}","${c.actionLabel}: ${c.actionUrl}",c.secondaryUrl?.let{"${c.secondaryLabel}: $it"}?:"",c.securityNote,"Need help? Contact your institutional eGMS administrator.","Open NHRC eGMS: ${c.portalUrl}","Local UAT links work on the host computer.").filter{it.isNotBlank()}.joinToString("\n\n")
  return RenderedEmail(c.subject.replace(Regex("[\\r\\n]+")," ").take(240),plain,html)
 }
}
